import React, { useState, useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { translations } from "./translations"; // ✅ import your translation file
import LanguageSelector from "./languageSelector.jsx"; // ✅ import your flag selector
import "./result.css";

function ResultPage() {
  const location = useLocation();
  const navigate = useNavigate();
  const {
    symptoms = [],
    predictions = [],
    symptom_details = [],
  } = location.state || {};

  // 🌐 Language setup
  const [language, setLanguage] = useState(
    () => localStorage.getItem("lang") || "en"
  );
  const hasSeenPopup = sessionStorage.getItem("seenLangPopup");
  const [showPopup, setShowPopup] = useState(!hasSeenPopup);

  const handleSelect = (lang) => {
    setLanguage(lang);
    localStorage.setItem("lang", lang);
    sessionStorage.setItem("seenLangPopup", "true");
    setShowPopup(false);
  };
  const langText = translations[language] || translations.en;

  useEffect(() => {
    console.log("🩺 Full backend response ↓");
    console.dir({ symptoms, predictions, symptom_details }, { depth: null });
  }, [symptoms, predictions, symptom_details]);

  return (
    <div className="result-container">
      {/* 🌐 First-time popup */}
      {showPopup && (
        <div className="language-popup">
          <div className="popup-box">
            <h3>{langText.chooseLangTitle}</h3>
            <p>{langText.chooseLangText}</p>
            <button onClick={() => handleSelect("en")}>English</button>
            <button onClick={() => handleSelect("kriol")}>Kriol</button>
          </div>
        </div>
      )}

      {/* 🌐 Flag Selector */}
      <div className="lang-toggle">
        <LanguageSelector language={language} onChange={handleSelect} />
      </div>

      <h2>{langText.summaryTitle}</h2>
      <p>{langText.summaryText}</p>

      {/* 🩻 Detected Symptoms Section */}
      <div className="result-section">
        <h3>{langText.detectedSymptoms}</h3>
        {symptom_details.length > 0 ? (
          symptom_details.map((item, i) => (
            <div key={i} className="symptom-card">
              <h4>• {item.symptom}</h4>
              <p>
                <b>{langText.description}:</b>{" "}
                {language === "kriol"
                  ? item.description_kriol || item.description
                  : item.description}
              </p>
              <p>
                <b>{langText.causes}:</b>{" "}
                {language === "kriol"
                  ? item.common_causes_kriol || item.common_causes
                  : item.common_causes}
              </p>
              <p>
                <b>{langText.advice}:</b>{" "}
                {language === "kriol"
                  ? item.advice_kriol || item.advice
                  : item.advice}
              </p>
            </div>
          ))
        ) : (
          <p>
            {language === "kriol"
              ? "Nating sik faind yet."
              : "No symptoms detected."}
          </p>
        )}
      </div>

      {/* 💊 Possible Conditions */}
      <div className="result-section">
        <h3>{langText.possibleConditions}</h3>
        <ul>
          {predictions.length > 0 ? (
            predictions.map((p, i) => (
              <li key={i}>
                <b>{p.disease}</b> — confidence: {Math.round(p.score * 100)}%
              </li>
            ))
          ) : (
            <li>
              {language === "kriol"
                ? "No risalt yet."
                : "No predictions available."}
            </li>
          )}
        </ul>
      </div>

      {/* 🔙 Back Button */}
      <div className="result-button-section">
        <button onClick={() => navigate("/")} className="btn-back">
          {langText.back}
        </button>
        <button onClick={() => navigate("/")} className="btn-back">
          {langText.suggestion}
        </button>
      </div>
    </div>
  );
}

export default ResultPage;
